+            true,
+            args -> new EmbeddingFloatResultEntry((Integer) args[0], (List<Float>) args[1])
+        );
+
+        static {
+            PARSER.declareInt(constructorArg(), new ParseField("index"));
+            PARSER.declareFloatArray(constructorArg(), new ParseField("embedding"));
+        }
